head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = "ULDSTF05810.xml";
scwin.fr_SecuGrpId;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.gBzProcsNo;
scwin.gAcptNo;
scwin.gListProcsStatCd;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.gAcptNo;
scwin.gViewerStat; // 처리시 뷰어=P,  조회시 뷰어=R
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD);
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD != '2') {
            $c.win.alert("[소속부변경]업무는 코스닥회사만 해당합니다. 회사을 다시 선택바랍니다");
        }
    }
};
scwin.fn_Search = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/SegmentChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=recvSegment&inputMessageId=SEG_CHG_RECV_OUT";
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var pSEG_TP_CD = $c.stf.getObjectValue(cmb_SEG_TP_CD);
        if ($c.stf.getObjectValue(cmb_SEG_TP_CD) == "") {
            pSEG_TP_CD = "A";
        }
        var url = "/SegmentChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listSegment&inputMessageId=SEG_CHG_INOUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        url += "&SEG_TP_CD=" + pSEG_TP_CD;
        url += "&PROCS_STAT_CD=" + $c.stf.getObjectValue(rdo_PROCS_STAT_CD);
        url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
        url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
        url += "&FINAL_YN=" + $c.stf.getObjectValue(final_YN);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.reset();
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.fn_OpenDetail = async function(row) {
    var formCd = dts_List_2.getCellData(row, "FORM_CD");
    var segChgTpCd = dts_List_2.getCellData(row, "SEG_CHG_TP_CD");
    var acptNo = dts_List_2.getCellData(row, "ACPT_NO");
    if (segChgTpCd == "04") {
        //신규상장 입력
        await $c.frame.CreateFrame("ULDSTF05814", "/lstproc/ULDSTF05814.gfm", "세그먼트 관리상세(신규상장)", 0, 0, 840, 330, "window", 0, 0, false);
    } else if (acptNo == "") {
        //공시부입력
        await $c.frame.CreateFrame("ULDSTF05815", "/lstproc/ULDSTF05815.gfm", "세그먼트 관리상세(신규상장)", 0, 0, 840, 730, "window", 0, 0, false);
    } else {
        if (formCd == "72088") {
            await $c.frame.CreateFrame("ULDSTF05811", "/lstproc/ULDSTF05811.gfm", "세그먼트 관리상세(신규지정요건)", 0, 0, 840, 815, "window", 0, 0, false);
        } else if (formCd == "72089") {
            await $c.frame.CreateFrame("ULDSTF05812", "/lstproc/ULDSTF05812.gfm", "세그먼트 관리상세(정기유지요건)", 0, 0, 840, 815, "window", 0, 0, false);
        } else if (formCd == "72090") {
            await $c.frame.CreateFrame("ULDSTF05813", "/lstproc/ULDSTF05813.gfm", "세그먼트 관리상세(지정취소)", 0, 0, 840, 330, "window", 0, 0, false);
        }
    }
};




// 클릭된 값 변수에 셋팅
scwin.fn_OpenRecvDetail = function(row, colid) {
    var segChgTpCd = dts_List_2.getCellData(row, "SEG_CHG_TP_CD");
    var acptNo = dts_List_2.getCellData(row, "ACPT_NO");
    if (segChgTpCd == "04") {
        $c.win.alert("신규상장으로 지정된 항목은 공시내역이 없습니다.");
        return;
    }
    if (acptNo == "") {
        $c.win.alert("공시부에서 입력한 항목은 공시내역이 없습니다.");
        return;
    }
    scwin.fn_setContnId(row);
    $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
};
scwin.fn_setContnId = function(obj) {
    if (eval(obj) > 0) {
        //그리드에서 선택시
        if (MaxTab_01.getSelectedTabIndex() == 1) {
            scwin.gAcptNo = dts_List_1.getCellData(eval(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_1.getCellData(eval(obj), "FORM_CD");
            scwin.gFormVer = dts_List_1.getCellData(eval(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_1.getCellData(eval(obj), "ISUR_CD");
            scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

        } else {
            scwin.gAcptNo = dts_List_2.getCellData(eval(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_2.getCellData(eval(obj), "FORM_CD");
            scwin.gFormVer = dts_List_2.getCellData(eval(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_2.getCellData(eval(obj), "ISUR_CD");
            scwin.gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R

        }
    }
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt_1.setValue("총 " + dts_List_1.getTotalRow() + "건");
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt_2.setValue("총 " + dts_List_2.getTotalRow() + "건");
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    scwin.fn_setContnId(row);
    $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    if (colid == "LIST_BZ_APPL_DDTM") {
        scwin.fn_OpenRecvDetail(row, colid);
    } else {
        scwin.fn_OpenDetail(row);
    }
};
scwin.btn_Search_1_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Search_2_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Close_1_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Close_2_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Excel_2_onclick = function() {
    if (dts_List_2.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_List_2, "세그먼트관리 목록", "", 8, 0);
    }
};
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.img_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top_1);
    $c.cm.PanelToGroupBox(panel_Top_2);
    MaxTab_01.setSelectedTabIndex(1);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetMinusDate2(vCurDate, 90));
    edt_EDATE.setValue(vCurDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_Search();
};
